            <li>Clear intake for account and product questions</li>
            <li>Designed for a simple, low-friction handoff</li>
          </ul>
        </section>
      `;

      const ContactForm = () => `
        <section class="support-form-panel">
          <div class="panel-heading">
            <h2>Contact support</h2>
            <p>Required fields are marked with an asterisk.</p>
